class TestSortTopGatewaysTable(unittest.TestCase):
    @staticmethod
    def table(*rows):
        return (
            "intro text\n\n"
            "<!-- TOP-GATEWAYS:START -->\n"
            "| Gateway | Stars | What it is | Jump to |\n"
            "|---|---|---|---|\n" + "".join(f"{row}\n" for row in rows) +
            "<!-- TOP-GATEWAYS:END -->\n\n"
            "> footer note\n"
        )

    ROW_SMALL = "| [Small](https://github.com/o/small) | <!--s:o/small-->⭐ 823<!--/s--> | tiny | [S](#s) |"
    ROW_MID = "| [Mid](https://github.com/o/mid) | <!--s:o/mid-->⭐ 36k<!--/s--> | middle | [M](#m) |"
    ROW_BIG = "| [Big](https://github.com/o/big) | <!--s:o/big-->⭐ 45.1k<!--/s--> | large | [B](#b) |"
    ROW_NO_SPAN = "| [Hosted](https://hosted.example) | — | SaaS, no repo | [H](#h) |"

    def test_out_of_order_rows_get_sorted_descending(self):
        out = sort_top_gateways_table(self.table(self.ROW_MID, self.ROW_SMALL, self.ROW_BIG))
        self.assertEqual(out, self.table(self.ROW_BIG, self.ROW_MID, self.ROW_SMALL))

    def test_sorted_input_is_unchanged(self):
        text = self.table(self.ROW_BIG, self.ROW_MID, self.ROW_SMALL)
        self.assertEqual(sort_top_gateways_table(text), text)

    def test_rows_without_a_count_sink_to_the_bottom(self):
        out = sort_top_gateways_table(
            self.table(self.ROW_NO_SPAN, self.ROW_SMALL, self.ROW_BIG)
        )
        self.assertEqual(out, self.table(self.ROW_BIG, self.ROW_SMALL, self.ROW_NO_SPAN))

    def test_content_outside_markers_is_untouched(self):
        out = sort_top_gateways_table(self.table(self.ROW_MID, self.ROW_BIG))
        self.assertTrue(out.startswith("intro text\n\n"))
        self.assertTrue(out.endswith("> footer note\n"))

    def test_missing_markers_raise(self):
        with self.assertRaises(ValueError):
            sort_top_gateways_table("| Gateway | Stars |\n|---|---|\n| a | 1 |\n")

    def test_both_readmes_carry_markers_and_stay_sorted(self):
        """The real files must keep the markers and the by-stars promise."""
        from pathlib import Path

        root = Path(__file__).resolve().parent.parent
        for name in ("README.md", "README.zh-CN.md"):
            text = (root / name).read_text(encoding="utf-8")
            self.assertEqual(
                sort_top_gateways_table(text), text, f"{name}: top-gateways table is out of order"
            )


class TestRenderReleases(unittest.TestCase):
    def test_empty_list_renders_placeholder(self):
        self.assertIn("No recent releases", render_releases_block([]))

    def test_renders_date_repo_and_link(self):
        block = render_releases_block(
            [
                {
                    "repo": "o/a",
                    "tag": "v1.2.0",
                    "name": "Big   release\nwith newline",
                    "published_at": "2026-06-10T12:00:00Z",
                    "url": "https://github.com/o/a/releases/tag/v1.2.0",
                }
            ]
        )
        # Plain-text date (not bold): items starting with a text node are
        # skipped by awesome-lint's list-item rule, keeping the block green.
        self.assertIn("- 2026-06-10 · ", block)
        self.assertNotIn("**2026-06-10**", block)
        self.assertIn("[o/a v1.2.0](https://github.com/o/a/releases/tag/v1.2.0)", block)
        self.assertIn("Big release with newline", block)

    def test_caps_at_twelve_entries(self):
        releases = [
            {
                "repo": f"o/r{i}",
                "tag": "v1",
                "name": "r",
                "published_at": f"2026-06-{i + 1:02d}T00:00:00Z",
                "url": "https://example.com",
            }
            for i in range(20)
        ]
        block = render_releases_block(releases)
        self.assertEqual(block.count("\n") + 1, 12)


if __name__ == "__main__":
    unittest.main()


class TestMaintenanceSignal(unittest.TestCase):
    """The quiet/archived table — the one number stars cannot give you.

    Stars are cumulative: a project that stopped shipping keeps its 36k and reads
    as healthy. LANDSCAPE.md tells readers to check the last commit before the
    feature matrix, so the list has to actually publish that check.
    """

    NOW = datetime(2026, 8, 12, tzinfo=timezone.utc)

    def _activity(self):
        return {
            "live/active": {"pushed_at": "2026-08-11T00:00:00Z", "archived": False},
            "quiet/sixmonths": {"pushed_at": "2026-01-09T00:00:00Z", "archived": False},
            "dead/archived": {"pushed_at": "2026-06-11T00:00:00Z", "archived": True},
        }

    def test_days_since_counts_whole_days(self):
        self.assertEqual(days_since("2026-08-02T00:00:00Z", self.NOW), 10)

    def test_active_repo_is_not_listed(self):
        rows = quiet_entries(self._activity(), now=self.NOW)
        self.assertNotIn("live/active", [r["repo"] for r in rows])

    def test_archived_sorts_before_merely_quiet(self):
        rows = quiet_entries(self._activity(), now=self.NOW)
        self.assertEqual([r["repo"] for r in rows], ["dead/archived", "quiet/sixmonths"])

    def test_archived_is_listed_even_when_recently_pushed(self):
        """An archive can be days old — recency must not hide it."""
        rows = quiet_entries(
            {"x/y": {"pushed_at": "2026-08-10T00:00:00Z", "archived": True}}, now=self.NOW
        )
        self.assertEqual(len(rows), 1)

    def test_render_marks_archived_and_quiet_differently(self):
        block = render_maintenance_block(quiet_entries(self._activity(), now=self.NOW))
        self.assertIn("archived", block.lower())
        self.assertIn("Quiet for", block)

    def test_render_says_so_when_everything_is_healthy(self):
        self.assertIn("No listed project", render_maintenance_block([]))
        self.assertIn("没有条目", render_maintenance_block([], zh=True))

    def test_both_readmes_carry_the_markers(self):
        for name in ("README.md", "README.zh-CN.md"):
            text = (REPO_ROOT / name).read_text(encoding="utf-8")
            with self.subTest(file=name):
                self.assertIn("<!-- MAINTENANCE:START -->", text)
                self.assertIn("<!-- MAINTENANCE:END -->", text)

"""Structural integrity tests for data/mcp_gateways.json.

This matrix answers "can this gateway actually govern agent traffic?" — a
question where an unsupported ✅ is worse than a blank, because the reader
is deciding whether an agent's tool calls are authorized at all. So the
shape these tests enforce is: every capability claim carries evidence, and
every row that was not verified says so instead of implying it was.
"""

import datetime
import json
import unittest
from pathlib import Path

from check_freshness import TRACKED

ROOT = Path(__file__).resolve().parent.parent
DATA = json.loads((ROOT / "data" / "mcp_gateways.json").read_text(encoding="utf-8"))
ROWS = DATA["gateways"]

CAPABILITY_FIELDS = (
    "tool_level_authorization",
    "oauth_obo_token_exchange",
    "secret_brokering",
    "audit_of_tool_invocations",
)
VERIFICATION_LEVELS = {"source_read", "docs_read", "readme_only", "not_assessed"}


class TestFileLevel(unittest.TestCase):
    def test_as_of_is_iso_date(self):
        datetime.date.fromisoformat(DATA["as_of"])

    def test_tracked_by_freshness_gate(self):
        self.assertIn("data/mcp_gateways.json", [path for _, path in TRACKED])

    def test_legend_documents_every_capability_field(self):
        for field in CAPABILITY_FIELDS:
            self.assertIn(field, DATA["legend"], f"legend is missing {field}")

    def test_rows_present(self):
        self.assertGreater(len(ROWS), 0)


class TestRows(unittest.TestCase):
    def test_every_row_names_its_verification_level(self):
        for row in ROWS:
            self.assertIn(
                row.get("verification"), VERIFICATION_LEVELS,
                f"{row.get('gateway', '?')}: verification must be one of {sorted(VERIFICATION_LEVELS)}",
            )

    def test_source_read_rows_pin_a_commit(self):
        """A source_read claim without a commit cannot be re-checked later."""
        for row in ROWS:
            if row.get("verification") == "source_read":
                self.assertTrue(
                    row.get("pinned_commit"),
                    f"{row['gateway']}: source_read rows must carry pinned_commit",
                )

    def test_unverified_rows_do_not_assert_capabilities(self):
        """The failure mode this guards: a row nobody checked still printing
        a confident yes, which reads identically to a verified one."""
        for row in ROWS:
            if row.get("verification") in {"not_assessed", "unknown"}:
                for field in CAPABILITY_FIELDS:
                    value = row.get(field)
                    text = json.dumps(value, ensure_ascii=False).lower() if value is not None else ""
                    self.assertNotIn(
                        '"yes"', text,
                        f"{row['gateway']}: {field} asserts yes on an unverified row",
                    )

    def test_gateway_names_unique(self):
        names = [row["gateway"] for row in ROWS]
        self.assertEqual(len(names), len(set(names)), "duplicate gateway rows")


if __name__ == "__main__":
    unittest.main()

"""Unit tests for build_llms_txt.py (renders against the real compare/*.md)."""

import re
import unittest

import build_llms_txt
from build_llms_txt import render


class TestLlmsTxt(unittest.TestCase):
    def setUp(self):
        self.txt = render()

    def test_llmstxt_shape(self):
        # spec: starts with an H1, then a blockquote summary
        self.assertTrue(self.txt.startswith("# Awesome AI Gateway\n"))
        self.assertIn("\n> ", self.txt)

    def test_required_sections_present(self):
        for h in ["## Core", "## Comparisons", "## Guides", "## Tools (interactive)",
                  "## Data (machine-readable, CC0)", "## Companion tools (same author)"]:
            self.assertIn(h, self.txt)

    def test_guides_and_tools_list_canonical_pages_only(self):
        # The interactive tools and the one canonical guide must be present…
        for url in ("reduce-llm-api-costs.html", "gateway-picker.html", "cost-calculator.html"):
            self.assertIn(f"https://cuihuan.github.io/awesome-ai-gateway/{url}", self.txt)
        # …while the three guides that canonicalize to compare/ successors stay out
        # (their winners are already listed under Comparisons).
        for gone in ("litellm-vs-openrouter.html", "openrouter-alternatives.html",
                     "self-hosted-llm-gateway.html"):
            self.assertNotIn(f"awesome-ai-gateway/{gone}", self.txt)

    def test_every_comparison_listed_with_absolute_url(self):
        articles = build_llms_txt._articles()
        self.assertGreaterEqual(len(articles), 1)
        for a in articles:
            self.assertIn(f"https://cuihuan.github.io/awesome-ai-gateway/compare/{a['slug']}.html", self.txt)

    def test_companion_tools_linked(self):
        self.assertIn("https://github.com/cuihuan/llm-gateway-bench", self.txt)
        self.assertIn("https://github.com/cuihuan/modelprobe", self.txt)

    def test_links_are_absolute(self):
        # every markdown link target in llms.txt must be an absolute URL
        for target in re.findall(r"\]\(([^)]+)\)", self.txt):
            self.assertTrue(target.startswith("https://"), f"non-absolute link: {target}")

    def test_ends_with_single_newline(self):
        self.assertTrue(self.txt.endswith("\n"))
        self.assertFalse(self.txt.endswith("\n\n"))


if __name__ == "__main__":
    unittest.main()

"""Unit tests for make_decision_tree.py pure functions (no PIL).

The headline invariant: every self-hostable gateway the decision tree
recommends must map to a repo actually tracked in data/projects.json — so the
shareable image can never drift from the list it advertises.
"""

import unittest

from make_decision_tree import (
    SELF_HOSTED_REPO,
    build_tree,
    self_hosted_slugs,
    tracked_repos,
)


class TestBuildTree(unittest.TestCase):
    def test_has_two_branches_hosted_and_self(self):
        kinds = [b["kind"] for b in build_tree("en")["branches"]]
        self.assertEqual(sorted(kinds), ["hosted", "self"])

    def test_every_leaf_has_a_condition_and_picks(self):
        for lang in ("en", "zh"):
            for b in build_tree(lang)["branches"]:
                self.assertTrue(b["leaves"])
                for leaf in b["leaves"]:
                    self.assertTrue(leaf["cond"].strip())
                    self.assertTrue(leaf["picks"], f"{lang} leaf has no picks")

    def test_en_and_zh_same_shape(self):
        en, zh = build_tree("en"), build_tree("zh")
        self.assertEqual(len(en["branches"]), len(zh["branches"]))
        for be, bz in zip(en["branches"], zh["branches"]):
            self.assertEqual(be["kind"], bz["kind"])
            self.assertEqual(len(be["leaves"]), len(bz["leaves"]))
            for le, lz in zip(be["leaves"], bz["leaves"]):
                # same recommendation slugs in both languages (only prose differs)
                self.assertEqual(le["picks"], lz["picks"])

    def test_returns_a_copy_not_the_constant(self):
        a = build_tree("en")
        a["branches"][0]["leaves"][0]["cond"] = "MUTATED"
        self.assertNotEqual(build_tree("en")["branches"][0]["leaves"][0]["cond"], "MUTATED")


class TestNoDriftFromList(unittest.TestCase):
    def test_self_hosted_picks_are_all_in_the_repo_map(self):
        # every self-host recommendation must have a known repo mapping
        unmapped = self_hosted_slugs(build_tree("en")) - set(SELF_HOSTED_REPO)
        self.assertEqual(unmapped, set(), f"tree recommends unmapped self-host gateways: {unmapped}")

    def test_repo_map_points_at_tracked_repos(self):
        tracked = tracked_repos()
        missing = {name: repo for name, repo in SELF_HOSTED_REPO.items() if repo not in tracked}
        self.assertEqual(missing, {}, f"tree recommends gateways not tracked in projects.json: {missing}")


if __name__ == "__main__":
    unittest.main()

"""Unit tests for make_social_preview.py pure data (no PIL).

Headline invariant (mirrors test_make_landscape): the card must not advertise a
gateway the README doesn't carry, and it must stay the GitHub-social 1280x640.
The rendering path (`render`) imports Pillow and is intentionally NOT exercised
here — Pillow is absent on the CI runner.
"""

